tool_input.command:
sqlite3 experiments.sqlite "SELECT id, artifacts_dir, git_commit FROM experiments ORDER BY id;" && echo ---- && for i in 7 11; do echo "== exp $i"; sqlite3 experiments.sqlite "SELECT metrics_json FROM experiments WHERE id=$i;" | python3 -c "
import json,sys
m=json.load(sys.stdin)
def show(d,ind=''):
    for k,v in d.items():
        if isinstance(v,dict):
            print(ind+k+':'); show(v,ind+'  ')
        elif isinstance(v,list): print(ind+k+': list['+str(len(v))+']')
        else: print(ind+f'{k}: {v}')
show(m)
"; done

cat > /tmp/showm.py <<'EOF'
import json,sys
m=json.load(open(sys.argv[1]))
def show(d,ind=''):
    for k,v in d.items():
        if isinstance(v,dict):
            print(ind+k+':'); show(v,ind+'  ')
        elif isinstance(v,list): print(ind+k+': list['+str(len(v))+']')
        else: print(ind+f'{k}: {v}')
show(m)
EOF
for i in 7 11; do echo "== exp $i"; d=$(sqlite3 experiments.sqlite "SELECT artifacts_dir FROM experiments WHERE id=$i;"); ls $d; python3 /tmp/showm.py $d/metrics.json; done
